# Owner approved 2026-11-06. This is a reporting projection; no legacy answer is rewritten.
INTEREST_MAPPING = {"seeking":"yes","open":"maybe","not_seeking":"no"}

@dataclass(frozen=True)
class Metric:
    key: str
    label: str
    source: str
    calculation: str
    exclusions: str
    unique_rule: str
    period: str
    filters: str
    permission: str
    missing: str = "Unavailable when source evidence or the required denominator is missing. Unknown is not zero."
    provenance: str = "Calculated from recorded platform data"

